import{_ as t,o as s,c as a,a4 as o}from"./chunks/framework.CpzWeSYQ.js";const h=JSON.parse('{"title":"JellyGo! 玩法与架构设计手记","description":"","frontmatter":{"title":"JellyGo! 玩法与架构设计手记","date":"2026-06-29T00:00:00.000Z","category":"造物手记","tags":["游戏开发","Phaser","TypeScript","联机","架构设计"]},"headers":[],"relativePath":"posts/jellygo-gameplay.md","filePath":"posts/jellygo-gameplay.md","lastUpdated":1782711754000}'),n={name:"posts/jellygo-gameplay.md"};function p(d,e,c,l,r,i){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="jellygo-玩法与架构设计手记" tabindex="-1">JellyGo! 玩法与架构设计手记 <a class="header-anchor" href="#jellygo-玩法与架构设计手记" aria-label="Permalink to &quot;JellyGo! 玩法与架构设计手记&quot;">​</a></h1><p>JellyGo! 是我独立开发的一款<strong>即时策略双人联机 Web 端对抗游戏</strong>。两个玩家控制建筑、生产发射果冻（能量）、占领敌方建筑，十分钟内看谁的总能量多。这篇整理一下它的核心玩法、视觉与联机架构设计。</p><h2 id="核心循环" tabindex="-1">核心循环 <a class="header-anchor" href="#核心循环" aria-label="Permalink to &quot;核心循环&quot;">​</a></h2><p>每局地图上有 11 座建筑，分属红方、蓝方、中立。建筑持续生产能量，玩家通过<strong>单击（发射 50% 能量）/ 双击（发射 100% 能量）</strong> 把果冻投向目标建筑。果冻不是瞬移，有移动速度：</p><ul><li>原始者 / 生产者：78 px/s（基速）</li><li>堡垒：46.8 px/s（慢而硬）</li><li>实验室：156 px/s（快而脆）</li></ul><p>果冻到达非己方建筑就触发战斗结算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>攻击力 = floor(果冻能量 / 防守方防守能力)</span></span></code></pre></div><p>攻击力 ≤ 守方能量则防守成功；攻击力 &gt; 守方能量则<strong>建筑被占领</strong>，新能量 = <code>floor(果冻能量 - 守方能量 × 防守系数)</code>。这个公式的核心思想是：守方&quot;吸收&quot;一部分攻击能量，剩余的转成新所有者的初始能量——既给了防守方一些容错，也让进攻方在优势局有滚雪球效应。</p><p>十分钟超时则按总能量判负。</p><h2 id="四类建筑" tabindex="-1">四类建筑 <a class="header-anchor" href="#四类建筑" aria-label="Permalink to &quot;四类建筑&quot;">​</a></h2><p><strong>原始者（House）</strong>——能变形的种子。只能升 1 级，每 6 秒生产 1 点能量，最大存量 10。当存量满 10 时可以花 10 能量<strong>变形</strong>为生产者、堡垒或实验室（保留剩余能量）。它是布局博弈的起点。</p><p><strong>生产者（Barracks）</strong>——扩张型。1/2/3 级的生产间隔从 5 秒加速到 1 秒，最大存量 10→30→50。果冻移速是基速 78 px/s（相对偏慢，因为能量产出高）。我故意把它的果冻移速从 100 降到 78，让&quot;产能高&quot;和&quot;投射慢&quot;形成权衡。</p><p><strong>堡垒（Fort）</strong>——防守型。无生产能力，最大存量大，有一个<strong>对所有玩家可见的攻击圈</strong>（虚线表示）。圈内的非己方果冻会被堡垒主动发射子弹追击，每颗子弹让果冻 -2 能量。1/2/3 级的圈半径是 80/100/120px，防守系数 1.5/1.9/2.3。我设计的意图是让堡垒成为&quot;必须绕开&quot;的地理障碍，而不是躲在后面的乌龟。</p><p><strong>实验室（Lab）</strong>——法术型。无生产能力，但果冻移速 156 px/s（2 倍基速，最快）。可以熬制三种法术：</p><table tabindex="0"><thead><tr><th>法术</th><th>效果</th><th>持续</th><th>等级</th><th>耗能</th><th>熬制时间</th></tr></thead><tbody><tr><td>感冒</td><td>失去生产能力，每 2 秒 -1 能量</td><td>永久</td><td>1</td><td>25</td><td>20 秒</td></tr><tr><td>冰冻</td><td>立刻冻结为中立建筑</td><td>永久</td><td>2</td><td>35</td><td>30 秒</td></tr><tr><td>感化</td><td>立刻把建筑阵营改成己方</td><td>永久</td><td>3</td><td>50</td><td>40 秒</td></tr></tbody></table><p>实验室熬制中不能发射果冻，熬制完成后进入&quot;待发射&quot;状态可以瞄准任意非己方单位释放。法术是<strong>立即生效</strong>的，不能被拦截。熬制过程如果实验室能量被削到不够施法，会自动终止——这个细节确保了&quot;法术不是无脑必中&quot;。</p><h2 id="视觉与渲染" tabindex="-1">视觉与渲染 <a class="header-anchor" href="#视觉与渲染" aria-label="Permalink to &quot;视觉与渲染&quot;">​</a></h2><p>最花心思的是<strong>程序化贴图系统</strong>。所有游戏贴图（建筑、果冻、子弹、星星、背景）都在 <code>BootScene.ts</code> 里用 <code>Phaser.Graphics</code> 画出来后调用 <code>generateTexture()</code> 落盘，<strong>不依赖任何外部图片资源</strong>。</p><p>为了让画面在桌面端不模糊，我加了一个 HiDPI 优化：常量 <code>TEX_SCALE = 4</code>，所有贴图按 4 倍尺寸生成，精灵 <code>setScale(1 / 4)</code> 缩回原始视觉尺寸。画布内部分辨率变成 3840×2400，再 <code>cameras.main.setZoom(4)</code> 填满视口。这样所有元素以 4x 像素密度渲染，桌面端清晰锐利。</p><p>分等级贴图采用<strong>纯白基底 + tint 阵营变色</strong>的策略：主体用 <code>0xFFFFFF, α=1</code> 画，tint 后呈现阵营色（红/蓝/灰）；细节用 <code>0x000000, α=0.25~0.55</code> 画，tint 后仍保持相对深色；高光用半透明白色增加立体感。这样一组贴图就能适配三个阵营。</p><p>每种建筑有 1~3 张等级贴图，等级越高装饰越华丽。比如军营 L3 是三旗 + 王冠 + 宝石盾徽 + 金边底座，堡垒 L3 是八城垛 + 三炮 + 中央塔楼 + 金旗大门。我画了 10 张贴图（House×1 + 其他×3），全部手画。</p><p>背景也是程序化生成的：深色渐变（<code>#1a2030</code> → <code>#141824</code>）+ 50px 网格线 + 三方领域微光 + 中心法阵装饰 + 双方阵地角标 + 400 个随机噪点。整体氛围是&quot;赛博战场&quot;。</p><h2 id="p2-联机架构" tabindex="-1">P2 联机架构 <a class="header-anchor" href="#p2-联机架构" aria-label="Permalink to &quot;P2 联机架构&quot;">​</a></h2><p>P1 阶段（单机 vs AI）已经完成，核心玩法打通。P2 阶段（WebSocket 双人联机）正在做，关键架构决策是<strong>权威服务器 + 客户端只发输入/渲染状态快照</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>共享层 shared/        ← 客户端与服务器共用</span></span>
<span class="line"><span>├── types.ts          ← 联机协议（GameSnapshot/InputMessage/LobbyMessage）</span></span>
<span class="line"><span>├── enums.ts          ← 枚举（Team/BuildingType/SpellType，字符串值）</span></span>
<span class="line"><span>├── constants.ts      ← 全局常量</span></span>
<span class="line"><span>├── interfaces.ts     ← 共享接口</span></span>
<span class="line"><span>└── config/           ← JSON 配置表</span></span>
<span class="line"><span></span></span>
<span class="line"><span>服务器 server/        ← 权威逻辑，20Hz tick</span></span>
<span class="line"><span>├── index.ts          ← HTTP 健康检查 + Socket.io 入口</span></span>
<span class="line"><span>├── GameServer.ts     ← 消息路由 + 房间 ID 生成</span></span>
<span class="line"><span>├── Room.ts           ← 房间管理（20Hz tick + 断线宽限/重连）</span></span>
<span class="line"><span>└── sim/              ← 8 个文件：GameSim/SimBuilding/...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>客户端 src/           ← 只发输入 + 渲染服务器快照</span></span>
<span class="line"><span>├── net/NetworkClient.ts  ← Socket.io 客户端单例</span></span>
<span class="line"><span>├── scenes/</span></span>
<span class="line"><span>│   ├── LobbyScene.ts     ← 大厅 8 状态机（创建/加入/重连）</span></span>
<span class="line"><span>│   └── GameScene.ts      ← 改造中：从本地逻辑改为渲染快照</span></span></code></pre></div><p>服务器跑在端口 3000（Node.js + Socket.io 4.8 + tsx 4.22），客户端 Vite dev server 在端口 3001，代理 <code>/socket.io</code> 到 3000。服务器 20Hz tick 生成快照广播，客户端用 <code>StateInterpolator</code> 做 100ms 插值让画面丝滑。</p><p>P2 阶段开发过程中修了 5 个值得记一笔的 bug：</p><ol><li><strong>邀请链接显示查询字符串</strong> —— <code>server/Room.ts</code> 返回的 <code>inviteLink</code> 只是 <code>?room=xxx</code>，P2 没法直接复制打开。改成在 <code>LobbyScene</code> 调 <code>NetworkClient.generateInviteLink(roomId)</code> 生成完整 URL。</li><li><strong><code>reconnect_ok</code> 缺 <code>yourTeam</code> 字段</strong> —— 重连后 NetworkClient 不知道自己是哪一方，状态机进 ERROR。3 文件协同补全 <code>yourTeam: Team</code>。</li><li><strong>waiting 阶段重连逻辑错误</strong> —— P1 刷新页面后服务器发 <code>reconnect_ok</code> 但游戏还没开始。改成根据 phase 分发：waiting 发 <code>room_created</code>，playing 发 <code>reconnect_ok</code> + 快照。</li><li><strong>创建房间界面按钮重叠</strong> —— 按钮宽 240px、间距 180px，重叠 60px。<code>createNeonButton</code> 加 <code>width</code> 参数，新界面用 160px。</li><li><strong>蓝方由 AI 控制（联机模式核心 bug）</strong> —— <code>GameScene</code> 没有 <code>init()</code> 方法，联机模式还是默认创建了 AI。改成加 <code>init(data)</code> + <code>isMultiplayer</code> 字段，联机模式不创建/不运行 AI。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>JellyGo! 是我目前为止最复杂的单体项目。从玩法到视觉到联机架构，每一层都需要反复推敲。P2 联机还有很多工作要做：GameScene 改造为状态渲染、UISystem 改造为输入发送、ngrok 内网穿透联调、正式地图平衡测试……</p><p>但看着&quot;按建筑发射果冻 → 战斗结算 → 占领转换阵营 → 能量溢出 → 升级变形 → 法术熬制 → 升级变形动画 → 堡垒主动追击 → 多选批量发射&quot;这一整套循环在浏览器里跑起来，那种&quot;从零开始搭世界&quot;的成就感，就是我熬夜写代码的燃料。</p><p>下一次更新应该会写 P2 联机协议设计和断线重连机制。继续肝。</p>`,32)])])}const u=t(n,[["render",p]]);export{h as __pageData,u as default};
